import moment from 'moment'
import dayjs from '../../src'
import advancedFormat from '../../src/plugin/advancedFormat'
import fs from 'fs'
import path from 'path'
dayjs.extend(advancedFormat)
const localeDir = path.join(__dirname, '../../src/locale')
const files = fs.readdirSync(localeDir).filter(f => f.endsWith('.js'))
it('compare ordinals', () => {
  const bad = []
  files.forEach((f) => {
    const name = f.replace('.js', '')
    /* eslint-disable global-require, import/no-dynamic-require */
    require(path.join(localeDir, f))
    let m
    try {
      m = require(`moment/locale/${name}`)
    } catch (e) { m = null }
    if (!m) return
    for (let d = 1; d <= 31; d += 1) {
      const date = `2018-05-${String(d).padStart(2, '0')}`
      const dj = dayjs(date).locale(name).format('Do')
      const mo = moment(date).locale(name).format('Do')
      if (dj !== mo) { bad.push(`${name} day ${d}: dayjs=${dj} moment=${mo}`); break }
    }
  })
  console.log(bad.join('\n'))
  console.log('total mismatching locales:', bad.length)
})
